{
    public async Task<PatchEditOperationResult> BuildAsync(
        string projectPath,
        IReadOnlyList<LocalCoderFileContext> selectedFileContexts,
        string rawJson,
        PatchIntent? intent = null,
        CancellationToken cancellationToken = default)
